(()=>{const section=document.querySelector('#about');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let queued=false;function update(){queued=false;const box=section.getBoundingClientRect(),distance=Math.max(1,section.offsetHeight-innerHeight);const raw=Math.max(0,Math.min(1,-box.top/distance)),p=raw*raw*(3-2*raw);section.style.setProperty('--philosophy-progress',reduced.matches?1:p);section.style.setProperty('--detail-reveal',reduced.matches?1:Math.max(0,Math.min(1,(raw-.25)/.45)));}function schedule(){if(!queued){queued=true;requestAnimationFrame(update);}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);reduced.addEventListener('change',schedule);update();})();